function formatPartOfSpeech(pos, affix) {
  if (pos === "N") {
    return "noun_meaning";
  } else if (pos === "V") {
    return "verb_meaning";
  } else if (pos === "J") {
    return "adj_meaning";
  } else if (
    affix &&
    (affix === "ly" ||
      affix === "ever" ||
      affix === "ably" ||
      affix === "st" ||
      affix === "ally") &&
    (pos === "U" || pos === "R")
  ) {
    return "adv_meaning";
  } else if (affix && affix === "a" && pos === "U") {
    return "adp_meaning";
  } else if (affix && affix === "ant" && pos === "U") {
    return "noun_meaning";
  }
}

